#include <stdio.h>
#include <thinkthen.h>

thinkthen_engine *tt = thinkthen_engine_new();

/* score takes the JSON door: a request in, JSON out */
const char *ask = "{\"score\": \"How urgent is this?\", "
    "\"levels\": [\"Routine.\", \"Soon.\", "
    "\"Immediate.\"], "
    "\"evidence\": \"Checkout is down for everyone.\"}";
char *out = thinkthen_call(tt, ask);

/* an outage lands near 2, "Immediate." */
puts(out ? out : thinkthen_error_message(tt));
thinkthen_free_string(out);
thinkthen_engine_free(tt);
